alter table public.community_challenges add column journey_template_slug text,add column journey_template_version integer,
 add constraint challenge_template_reference foreign key(journey_template_slug,journey_template_version) references public.journey_templates(slug,version),
 add constraint challenge_template_pair check((journey_template_slug is null)=(journey_template_version is null));
create function public.curated_challenge_guard() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
declare template journey_templates;begin
 if TG_OP='UPDATE' and old.journey_template_slug is not null and
  (new.journey_template_slug,new.journey_template_version) is distinct from (old.journey_template_slug,old.journey_template_version)
  then raise exception 'Create another challenge to change its route';end if;
 if new.journey_template_slug is not null then
  select * into template from journey_templates where slug=new.journey_template_slug and version=new.journey_template_version;
  if not found then raise exception 'Route unavailable';end if;
  if new.metric<>'virtual_distance' or new.scope<>'collective' then raise exception 'Curated routes require collective Virtual distance';end if;
  new.target:=template.target_km;
  new.route_version:=template.slug||'@'||template.version||':'||template.geometry_version;
 end if;
 return new;
end;$$;
create trigger curated_challenge_guard before insert or update on public.community_challenges for each row execute function public.curated_challenge_guard();

alter function public.social_challenge_values(uuid) rename to social_challenge_values_without_route;
revoke all on function public.social_challenge_values_without_route(uuid) from public,anon,authenticated;
create function public.social_challenge_values(p_challenge uuid) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare summary jsonb;ch community_challenges;template journey_templates;begin
 summary:=social_challenge_values_without_route(p_challenge);
 if summary is null then return null;end if;
 select * into ch from community_challenges where id=p_challenge;
 if ch.journey_template_slug is null then return summary;end if;
 select * into template from journey_templates where slug=ch.journey_template_slug and version=ch.journey_template_version;
 return summary||jsonb_build_object('route',jsonb_build_object('slug',template.slug,'version',template.version,'geometryVersion',template.geometry_version,'title',template.snapshot->>'title','targetKm',template.target_km::text));
end;$$;
create function public.social_journey_catalog() returns jsonb
language plpgsql stable security definer set search_path=public,pg_temp as $$
begin
 if auth.uid() is null or not social_enabled() then raise exception 'Sign in to view routes';end if;
 return (select coalesce(jsonb_agg(snapshot order by target_km,slug),'[]') from journey_templates);
end;$$;
create function public.social_journey_route(p_challenge uuid) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare summary jsonb;template jsonb;ch community_challenges;credited numeric;begin
 summary:=social_challenge_values(p_challenge);
 if summary is null then raise exception 'Challenge unavailable';end if;
 select * into ch from community_challenges where id=p_challenge;
 select snapshot into template from journey_templates where slug=ch.journey_template_slug and version=ch.journey_template_version;
 if template is null then raise exception 'No curated route on this challenge';end if;
 credited:=least((summary->>'total')::numeric,ch.target);
 return jsonb_build_object('summary',summary,'template',template,
 'reached',(select coalesce(jsonb_agg(w->>'occurrenceId' order by n),'[]') from jsonb_array_elements(template->'waypoints') with ordinality e(w,n) where (w->>'cumulativeKm')::numeric<=credited),
 'next',(select w from jsonb_array_elements(template->'waypoints') with ordinality e(w,n) where (w->>'cumulativeKm')::numeric>credited order by n limit 1));
end;$$;
create or replace function public.social_challenges(p_community uuid,p_action text default 'list',p_data jsonb default '{}') returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare ch community_challenges;uid uuid:=auth.uid();is_virtual boolean;selected text[];selection text;desired text;
begin
 if uid is null or not social_enabled() or not social_member(p_community,uid) then raise exception 'Community unavailable';end if;
 if p_data->>'journey_template_slug' is not null and p_data->>'metric' is distinct from 'virtual_distance' then raise exception 'Curated routes require Virtual distance';end if;
 if p_action='close' then
  if not social_admin(p_community,uid) then raise exception 'Not authorized';end if;
  if not social_rate('challenge-close:'||uid,10) then raise exception 'Please try again shortly';end if;
  select * into ch from community_challenges where id=(p_data->>'id')::uuid and community_id=p_community for update;
  if not found or ch.status<>'active' then raise exception 'Only active challenges can be closed';end if;
  update community_challenges set status='closed',closed_at=clock_timestamp() where id=ch.id;
  return social_challenges_legacy(p_community,'list','{}');
 end if;
 if p_action='list' then return social_challenges_legacy(p_community,p_action,p_data);end if;
 if p_action in('join','leave') then raise exception 'All Community members participate automatically';end if;
 if p_action<>'create' then
  select * into ch from community_challenges where id=(p_data->>'id')::uuid and community_id=p_community;
 end if;
 is_virtual:=p_data->>'metric'='virtual_distance' or ch.metric='virtual_distance';
 if p_action='update' and ch.metric='virtual_distance' and ch.status='draft' and p_data->>'metric'<>'virtual_distance' then
  return social_challenges_legacy(p_community,p_action,p_data);
 end if;
 if not coalesce(is_virtual,false) then return social_challenges_legacy(p_community,p_action,p_data);end if;
 if not social_admin(p_community,uid) then raise exception 'Not authorized';end if;
 if not social_rate('virtual-challenge:'||uid,10) then raise exception 'Please try again shortly';end if;
 if p_action in('create','update') then
  if p_action='update' and (ch.id is null or ch.metric<>'virtual_distance') then raise exception 'Create a new challenge to use Virtual distance';end if;
  if p_data->>'metric'<>'virtual_distance' then raise exception 'Create a new challenge to change its measure';end if;
  if p_data->>'scope'<>'collective' then raise exception 'Virtual-distance challenges are collective';end if;
  if not exists(select 1 from pg_timezone_names where name=p_data->>'time_zone') then raise exception 'Invalid timezone';end if;
  selection:=coalesce(p_data->>'activity_scope','all');
  selected:=array(select jsonb_array_elements_text(coalesce(p_data->'types','[]')));
  if selection not in('all','selected') or (selection='selected' and cardinality(selected)=0)
   or not selected<@array['run','ride','walk','strength','yoga','hike','swim','meditation','restore','other'] then raise exception 'Choose eligible activity types';end if;
  if selection='all' then selected:='{}';end if;
  desired:=coalesce(p_data->>'status','active');
  if p_action='create' then
   if desired not in('draft','active') then raise exception 'Invalid journey status';end if;
   insert into community_challenges(community_id,creator_id,title,metric,target,scope,types,activity_scope,starts_on,ends_on,time_zone,status,journey_policy_version,activated_at,journey_template_slug,journey_template_version)
    values(p_community,uid,btrim(p_data->>'title'),'virtual_distance',(p_data->>'target')::numeric,'collective',selected,selection,
     (p_data->>'starts_on')::date,nullif(p_data->>'ends_on','')::date,p_data->>'time_zone',desired,'journey-distance-v1',case when desired='active' then now() end,nullif(p_data->>'journey_template_slug',''),(p_data->>'journey_template_version')::integer)
    returning * into ch;
  else
   if ch.status<>'draft' then desired:=ch.status;end if;
   if desired not in('draft','active','closed','cancelled') then raise exception 'Invalid journey status';end if;
   update community_challenges set title=btrim(p_data->>'title'),target=(p_data->>'target')::numeric,
    types=selected,activity_scope=selection,starts_on=(p_data->>'starts_on')::date,ends_on=nullif(p_data->>'ends_on','')::date,
    time_zone=p_data->>'time_zone',status=desired,
    journey_template_slug=case when p_data?'journey_template_slug' then nullif(p_data->>'journey_template_slug','') else journey_template_slug end,
    journey_template_version=case when p_data?'journey_template_version' then (p_data->>'journey_template_version')::integer else journey_template_version end,activated_at=case when desired='active' then coalesce(activated_at,now()) else activated_at end
    where id=ch.id;
  end if;
  if p_data?'cover_path' then perform social_set_challenge_cover(ch.id,p_community,p_data->>'cover_path');end if;
 elsif p_action='close' then
  if ch.status<>'active' then raise exception 'Only active journeys can be closed';end if;
  update community_challenges set status='closed',closed_at=clock_timestamp() where id=ch.id;
 elsif p_action='cancel' then
  update community_challenges set status='cancelled' where id=ch.id;
 elsif p_action='cover' then perform social_set_challenge_cover(ch.id,p_community,p_data->>'cover_path');
 else raise exception 'Unknown journey action';end if;
 return social_challenges_legacy(p_community,'list','{}');
end;$$;

revoke all on function public.social_challenge_values(uuid),public.social_journey_catalog(),public.social_journey_route(uuid) from public,anon;
grant execute on function public.social_challenge_values(uuid),public.social_journey_catalog(),public.social_journey_route(uuid) to authenticated;
